634			t.Fatalf("use success=%d failed=%d, want 10/10", success, failed)
635		}
636		c, _ := s.Commitment("c1")
637		if c.Used != 10 || c.Unused() != 0 {
638			t.Fatalf("commitment: used=%d unused=%d", c.Used, c.Unused())
639		}
640		st, _ := s.PartStatus("part1", nowOK)
641		if st.PhysicalRemaining != 0 {
642			t.Fatalf("physical remaining = %d, want 0", st.PhysicalRemaining)
