6		"time"
7	)
8	
9	// 购买时刻边界回归：产品购买时刻为 t0（保修 30 天、除外 FAULTX），备件初始
10	// 库存 10 件，预留数量 4 件，承诺到期时刻晚于购买时刻。当前时刻在购买时刻
11	// 之前时一律不合格且拒绝原因只有购买时间在未来；当前时刻恰好等于购买时刻
12	// 时未命中除外规则的请求开始合格。
13	
14	func TestReserveBeforePurchaseTime(t *testing.T) {
15		s := newStore(t)
16		now := t0.Add(-time.Second)
17	
18		// 资格查询：不合格，拒绝原因只有购买时间在未来。
19		e, err := s.Evaluate("r1", now)
20		if err != nil {
21			t.Fatalf("evaluate: %v", err)
22		}
23		if e.Eligible || len(e.Reasons) != 1 || e.Reasons[0] != ReasonPurchaseInFuture {
24			t.Fatalf("before purchase: got %+v", e)
25		}
26	
27		// 请求视图同样显示不合格，且没有任何承诺明细。
28		view, err := s.RequestView("r1", now)
29		if err != nil {
30			t.Fatalf("request view: %v", err)
31		}
