1	package warranty
2	
3	import (
4		"errors"
5		"math"
6		"testing"
7		"time"
8	)
9	
10	// 重复登记的保护：已登记的非空编号再次提交时一律报 ErrDuplicateID，
11	// 无论新条款是否合法；原产品的购买时刻、保修天数和除外集合完整保留，
12	// 资格判断、预留与历史依据都继续按第一次成功登记的条款执行。
13	
14	// checkProductTerms 校验取回的产品资料与首次登记的条款完全一致。
15	func checkProductTerms(t *testing.T, s *Store, id string, purchase time.Time, days int, codes ...string) {
16		t.Helper()
17		p, err := s.Product(id)
18		if err != nil {
19			t.Fatalf("product %q: %v", id, err)
20		}
21		if !p.PurchaseTime.Equal(purchase) {
22			t.Fatalf("product %q purchase time = %v, want %v", id, p.PurchaseTime, purchase)
23		}
24		if p.WarrantyDays != days {
25			t.Fatalf("product %q warranty days = %d, want %d", id, p.WarrantyDays, days)
26		}
27		if len(p.ExcludedCodes) != len(codes) {
28			t.Fatalf("product %q excluded codes = %v, want exactly %v", id, p.ExcludedCodes, codes)
29		}
30		for _, c := range codes {
31			if _, ok := p.ExcludedCodes[c]; !ok {
32				t.Fatalf("product %q excluded codes = %v, missing %q", id, p.ExcludedCodes, c)
33			}
34		}
35	}
36	
37	// 新条款与旧条款明显不同（购买时刻、保修天数、除外清单全部改变）时，
38	// 重复登记仍报 ErrDuplicateID，原记录三项条款完整保留，不是部分保留。
39	func TestDuplicateProductDifferentTermsKeepsOriginal(t *testing.T) {
40		s := NewStore()
41		if err := s.RegisterProduct("p1", t0, 30, []string{"FAULTX", "FAULTY"}); err != nil {
42			t.Fatalf("register product: %v", err)
43		}
44		// 三项条款全部不同的合法新提交。
45		err := s.RegisterProduct("p1", t0.Add(5*day), 300, []string{"FAULTZ"})
46		if !errors.Is(err, ErrDuplicateID) {
47			t.Fatalf("duplicate with different terms: got %v, want ErrDuplicateID", err)
48		}
49		// 原条款完整保留：购买时刻、天数、除外集合都不被新提交改动。
50		checkProductTerms(t, s, "p1", t0, 30, "FAULTX", "FAULTY")
51	}
