53	// 重复编号同时带有非法条款时，编号重复优先于参数校验：报 ErrDuplicateID
54	// 而不是 ErrInvalidParam，原记录不被清空或部分替换。
55	func TestDuplicateProductInvalidTermsStillDuplicate(t *testing.T) {
56		cases := []struct {
57			name     string
58			purchase time.Time
59			days     int
60			codes    []string
61		}{
62			{"zero days", t0, 0, nil},
63			{"negative days", t0, -5, nil},
64			{"unrepresentable expiry", t0, math.MaxInt, nil},
65			{"empty excluded code", t0, 10, []string{""}},
66			{"empty code among valid", t0, 10, []string{"FAULTZ", ""}},
67		}
68		for _, tc := range cases {
69			t.Run(tc.name, func(t *testing.T) {
70				s := NewStore()
71				if err := s.RegisterProduct("p1", t0, 30, []string{"FAULTX"}); err != nil {
72					t.Fatalf("register product: %v", err)
73				}
74				err := s.RegisterProduct("p1", tc.purchase, tc.days, tc.codes)
75				if !errors.Is(err, ErrDuplicateID) {
