86	// 重复登记被拒绝后，资格继续按原购买时刻与原期限判断：按原条款仍在保的
87	// 请求不因新期限较短而被拒绝；按原条款已过保的请求不借较长的新期限重新
88	// 合格。原清单中的除外故障仍被拒绝，仅出现在新清单中的故障不构成除外。
89	// 直接查询资格与按请求查看资格依据都显示原保修条款。
90	func TestDuplicateRejectionKeepsOriginalEligibility(t *testing.T) {
91		s := NewStore()
92		if err := s.RegisterProduct("p1", t0, 30, []string{"FAULTX"}); err != nil {
93			t.Fatalf("register product: %v", err)
94		}
95		for _, r := range []struct{ id, fault string }{
96			{"rPlain", "FAULTY"},
97			{"rExcluded", "FAULTX"},
98			{"rNewOnly", "FAULTZ"},
99		} {
